import gzip, re, collections
from pathlib import Path

def scan(path, limit_print=0):
    p=Path(path)
    c=collections.Counter()
    sem=[]
    slow=[]
    pre_new=pre_c=0
    npre=0
    running=[]
    decode_re=re.compile(r"#running-req:\s*(\d+).*?gen throughput \(token/s\):\s*([0-9.]+)")
    pre_re=re.compile(r"#new-token:\s*(\d+),\s*#cached-token:\s*(\d+)")
    with gzip.open(p,"rt",errors="replace") as f:
        for line in f:
            if "semaphore" in line:
                c["sem"]+=1
                m=re.search(r"waited ([0-9.]+)s", line)
                if m: sem.append(float(m.group(1)))
            if "slow agentic" in line:
                c["slow"]+=1
                m=re.search(r"elapsed=([0-9.]+)", line)
                if m: slow.append(float(m.group(1)))
            if "Prefill batch" in line:
                m=pre_re.search(line)
                if m:
                    npre+=1
                    pre_new+=int(m.group(1)); pre_c+=int(m.group(2))
            if "Decode batch" in line:
                m=decode_re.search(line)
                if m:
                    running.append(int(m.group(1)))
            if "Dynamic filter dropped" in line:
                c["drop"]+=1
            if "fully-async" in line or "public-fully" in line:
                c["async"]+=1
    def pct(xs,p):
        if not xs: return None
        xs=sorted(xs); return xs[int((len(xs)-1)*p)]
    hit = pre_c/(pre_new+pre_c) if pre_new+pre_c else None
    print(path)
    print("  sem lines", c["sem"], "p50", pct(sem,.5), "p90", pct(sem,.9), "max", pct(sem,1))
    print("  slow", c["slow"], "p50", pct(slow,.5), "max", pct(slow,1))
    print("  prefill", npre, "hit", None if hit is None else round(hit,3), "new_k", round(pre_new/1000,1), "cached_k", round(pre_c/1000,1))
    print("  decode", len(running), "run_mean", None if not running else round(sum(running)/len(running),2), "run_max", max(running) if running else None)
    print("  drops", c["drop"])

for run in ["run-a","run-b"]:
    for pod in ["master","worker"]:
        scan(f"/workspace/logs/historical/{run}/{pod}.log.gz")
